// Construct an empty UTF-16 string as specified by the default constructor
poppler::ustring *ustr = new poppler::ustring();
// Validate postcondition: default-constructed string must be empty
FUZZ_ASSERT(ustr->size() == 0, "Default poppler::ustring should be empty");
// Output: ustr remains owned by the fuzzer runtime for future use
/* Validation: Constructs a valid, empty ustring and asserts emptiness; no inputs consumed. */

// Destroy the provided ustring object; it must be valid and not previously destroyed
delete ustr;
/* Validation: Properly releases a valid ustring; no outputs returned to avoid double free. */

// Convert the UTF-16 string to UTF-8 byte_array. The call is const and does not consume 'ustr'.
poppler::byte_array tmp = ustr->to_utf8();
// Persist the returned buffer for downstream consumers
poppler::byte_array *utf8 = new poppler::byte_array(std::move(tmp));
FUZZ_ASSERT(utf8 != nullptr, "Allocation for UTF-8 buffer failed");
// Output both the original string (still valid) and the produced UTF-8 buffer
/* Validation: Preserves input ustr, exposes produced byte_array; no API constraints violated. */

// Convert the UTF-16 string to a Latin-1 encoded std::string
std::string latin1 = ustr->to_latin1();
// Materialize as a byte_array so it can be pooled by the fuzzer runtime
poppler::byte_array *latin1_bytes = new poppler::byte_array(latin1.begin(), latin1.end());
FUZZ_ASSERT(latin1_bytes != nullptr, "Allocation for Latin-1 buffer failed");
// Output both original string and the produced byte buffer
/* Validation: Preserves input ustr and returns a pooled buffer; acknowledges potential lossy conversion. */

// Generate a random UTF-8 input buffer
