const char *ptr = (len == -1) ? s.c_str() : s.data();
// Construct ustring from UTF-8
poppler::ustring tmp = poppler::ustring::from_utf8(ptr, len);
// Heap-allocate and assign so the runtime can manage lifetime
poppler::ustring *ustr = new poppler::ustring();
*ustr = tmp; // assign constructed value
FUZZ_ASSERT(ustr != nullptr, "Allocation for ustring failed");
